 private static IEnumerable<P25Discovery> SiteDiscoveries(PacketObservation p){var catalog=new P25Catalog();catalog.Observe(p);return catalog.Rows.Select(r=>r.Value).ToArray();}
 private void QueueSite(SiteChannelData? c){if(c==null){siteUnresolved++;return;}if(c.Evidence.StartsWith("Provisional")&&(c.Protocol=="P25"?saveTentative.IsChecked:dmrSaveTentative.IsChecked)!=true){siteUnresolved++;return;}if(siteQueue.Count<2000||siteQueue.ContainsKey(c.Key))siteQueue[c.Key]=c;}
 private readonly Dictionary<string,string> dmrScopes=[];
 private void ObserveDmrForSaving(DmrReception r){if(r.Context.Replay)return;sharedLcnResearch.Observe(r);string key=r.Context.Key+":"+r.Context.FrequencyHz;if(r.Fields.LinkValid&&r.Fields.Network.HasValue){if(dmrScopes.Count>512)dmrScopes.Clear();dmrScopes[key]=$"{r.Fields.SystemType}:NET {r.Fields.Network}";}string scope=dmrScopes.GetValueOrDefault(key,$"{r.Fields.SystemType}:provisional:{key}");if(r.Fields.LinkValid&&r.Fields.Group&&r.Fields.Destination is uint tg)ObserveTalkgroup(scope,(int)tg,r.Seen);if(dmrSaveSites.IsChecked==true&&siteDmrEvidence.Observe(r)>=(dmrSaveTentative.IsChecked==true?1:3))QueueSite(SiteChannelData.FromDmr(r));}
 private void CollectMappedTrunkChannels(){lock(dmrTrunkRadio.Sync){var m=dmrTrunkRadio.Model;if(!m.Running||m.Profile.Protocol=="P25")return;var identity=m.DmrIdentity;string net=identity.Network is int n?$"Network {n}":"Profile "+m.Profile.Name+" ["+m.Profile.Id[..Math.Min(8,m.Profile.Id.Length)]+"]";string site=identity.Site is int s?$"Site {s}":"Unresolved site";foreach(var c in m.AvailableCalls(DateTimeOffset.UtcNow)){var carrier=m.Profile.Carriers.FirstOrDefault(x=>x.Hz==c.Hz);if(carrier==null)continue;QueueSite(new("DMR",["DMR",m.Profile.Protocol,net,site],$"DMR:{m.Profile.Protocol}:{net}:{site}",c.Hz,"LCN "+carrier.Lcn,"Mapped voice carrier",$"{m.Profile.Protocol}; {net}; {site}; TDMA carrier",null,carrier.Confirmed&&identity.Network.HasValue&&identity.Site.HasValue?"Mapped from confirmed carrier / CRC-valid status":"Provisional mapped carrier",c.Seen));}}}
 private void ObserveTalkgroups(PacketObservation p){if(!p.IsValidated)return;string scope=$"P25:{p.P25Identity?.Wacn:X5}-{p.P25Identity?.SystemId:X3}";if(p.P25Identity?.Wacn==null||p.P25Identity?.SystemId==null)scope+=$":NAC {p.P25Identity?.Nac:X3}:{p.FrequencyHz}";foreach(var a in p.P25Assignments??[])ObserveTalkgroup(scope,a.TalkgroupId,p.ObservedUtc);}
 private void ObserveTalkgroup(string scope,int tg,DateTimeOffset seen){if(talkgroupsReadOnly)return;string key=scope+":"+tg;var row=talkgroupRows.FirstOrDefault(r=>r.Key==key);if(row==null){if(talkgroupRows.Count>=10000)return;row=new(){Key=key,System=scope,Talkgroup=tg};talkgroupRows.Add(row);}row.Seen=seen;row.Count++;talkgroupDirty=true;}
 private void FlushSiteSaving(){talkgroupGrid.CommitEdit(DataGridEditingUnit.Cell,true);talkgroupGrid.CommitEdit(DataGridEditingUnit.Row,true);dmrTalkgroupGrid.CommitEdit(DataGridEditingUnit.Cell,true);dmrTalkgroupGrid.CommitEdit(DataGridEditingUnit.Row,true);siteSaveAt=talkgroupsSaveAt=DateTimeOffset.MinValue;TickSiteSaving();if(siteQueue.Count>0)File.WriteAllText(Path.Combine(dataFolder,pendingReadOnly?"pending-site-channels-recovered.json":"pending-site-channels.json"),JsonSerializer.Serialize(siteQueue.Values));}
 private void TickSiteSaving(){var now=DateTimeOffset.UtcNow;if(now>=siteSaveAt&&dmrSaveSites.IsChecked==true)CollectMappedTrunkChannels();if(now>=siteSaveAt&&siteQueue.Count>0){siteSaveAt=now.AddSeconds(1);try{if(FrequencyManager.SaveSiteChannels(siteQueue.Values.ToArray()) is {} saved){siteAdded+=saved.Added;siteUpdated+=saved.Updated;siteQueue.Clear();string pending=Path.Combine(dataFolder,"pending-site-channels.json");if(!pendingReadOnly&&File.Exists(pending))File.Delete(pending);}}catch(Exception ex){siteSaveStatus.Text="Site save failed; pending retained: "+ex.Message;return;}}siteSaveStatus.Text=$"Added {siteAdded}; updated {siteUpdated}; pending {siteQueue.Count}; unresolved/provisional {siteUnresolved}; held for review {FrequencyManager.HeldDiscoveryCount}";
 if(!talkgroupsReadOnly&&talkgroupDirty&&now>=talkgroupsSaveAt){talkgroupsSaveAt=now.AddSeconds(3);try{if(!((ListCollectionView)talkgroupGrid.ItemsSource).IsEditingItem&&!((ListCollectionView)dmrTalkgroupGrid.ItemsSource).IsEditingItem){File.WriteAllText(talkgroupsFile+".tmp",JsonSerializer.Serialize(talkgroupRows));File.Move(talkgroupsFile+".tmp",talkgroupsFile,true);talkgroupDirty=false;talkgroupGrid.Items.Refresh();dmrTalkgroupGrid.Items.Refresh();}}catch(Exception ex){Log("Talkgroups: "+ex.Message);}}}
